      bam_parameters_ptr->buf_siz = &lrec_size;
      bam_parameters_ptr->lrec_siz = NULL;
      dfsetbam(gr00_sw_ptr,bam_parameters_ptr);
      /* SW00LRP contains buffer pointer (from buf_ptr) */
      /* SW00LRB contains buffer size (from buf_siz) */
      gr00_lrec_ptr = dfred(gr00_sw_ptr,DFRED_BAM|DFRED_CURRENT);
      /* SW00BAM #BIT0 is set to 1 (set to 0 upon return) */
      /* SW00RT3 #BIT7 is set to 1 if LLR */
      if (DF_ER(gr00_sw_ptr))
      {
        /* serious error occurred */
      }
      else /* no serious error */
      {
        if(DF_ERBAM(gr00_sw_ptr))
        {
          /* BAM error, not serious */
          /* SW00RT3 #BIT0 is set to 1   -or- */
          /* SW00RT3 #BIT1 is set to 1 */
        }
        else
        {
          /* now the user has the LLR available in the buffer */
          /* SW00REC contains open MLL pointer 
             (copied to gr00_lrec_ptr) */
        }
      }
    }
    else /* LLR not found or serious error */
    {
      if (DF_ER(gr00_sw_ptr))
      {
        /* serious error occurred */
      }
    }
  } while (DF_OK(gr00_sw_ptr)); /* do while more Key 80 LRECs */
  dfcls(gr00_sw_ptr,0);
  free((void *)buffer_ptr); /* release buffer */ 

